#!/usr/bin/env node
// Scan all session logs for skill tool invocations.
import fs from 'fs';
import zlib from 'zlib';
import path from 'path';
import os from 'os';

const base = path.join(os.homedir(), '.dsh', 'sessions');
const ZSTD_MAGIC = Buffer.from([0x28, 0xb5, 0x2f, 0xfd]);
function zstdDecompressAll(buf) {
  const idxs = [];
  for (let i = 0; (i = buf.indexOf(ZSTD_MAGIC, i)) >= 0; i += 4) idxs.push(i);
  if (idxs.length <= 1) { try { return zlib.zstdDecompressSync(buf).toString('utf8'); } catch { return buf.toString('utf8'); } }
  let out = '';
  for (let k = 0; k < idxs.length; k++) {
    const start = idxs[k], end = k + 1 < idxs.length ? idxs[k + 1] : buf.length;
    try { out += zlib.zstdDecompressSync(buf.subarray(start, end)).toString('utf8'); } catch {}
  }
  return out;
}
function load(fp) {
  const s = zstdDecompressAll(fs.readFileSync(fp));
  const ev = [];
  for (const l of s.split('\n')) { if (!l) continue; try { ev.push(JSON.parse(l)); } catch {} }
  return ev;
}

// Candidate skill names: the user's own skills in the repo (with SKILL.md)
const repoSkills = ['decision-options','grill-me','i-have-adhd','long-form-corpus-rewrite','tdd','token-frugal','tool-call-hygiene','zentao-analyzer'];
// Plus other skills that may appear (built-in / shared)
const extraSkills = ['diagnose-windows-sandbox-acl','openviking-memory','openviking-skills','ov-experience-memory'];
const allSkills = [...repoSkills, ...extraSkills];

const usedSessions = {}; // skill -> Set of session ids
const usedCounts = {};   // skill -> total invocations
const mentionedSessions = {}; // weak: skill name appears in any text
allSkills.forEach(s => { usedSessions[s] = new Set(); usedCounts[s] = 0; mentionedSessions[s] = new Set(); });

let files = [];
(function walk(p) {
  for (const e of fs.readdirSync(p, { withFileTypes: true })) {
    const fp = path.join(p, e.name);
    if (e.isDirectory()) walk(fp);
    else if (/\.jsonl\.zstd$/.test(e.name)) files.push(fp);
  }
})(base);

let totalCalls = 0;
for (const fp of files) {
  const ev = load(fp);
  const sid = path.basename(path.dirname(fp)).replace(/^session-/, '').slice(0, 8);
  for (const e of ev) {
    if (e.type === 'tool/call' && e.data) {
      const nm = e.data.name;
      if (nm === 'skill') {
        let arg = {};
        try { arg = JSON.parse(e.data.arguments || '{}'); } catch {}
        const skillName = arg.name;
        if (skillName && allSkills.includes(skillName)) {
          usedSessions[skillName].add(sid);
          usedCounts[skillName]++;
          totalCalls++;
        } else if (skillName) {
          // unknown skill name invoked - record generically
          usedCounts['__' + skillName] = (usedCounts['__' + skillName] || 0) + 1;
          (usedSessions['__' + skillName] = usedSessions['__' + skillName] || new Set()).add(sid);
          totalCalls++;
        }
      }
    }
    // weak mention signal: any text containing the skill name as a token
    if (e.data && e.data.content) {
      const txt = typeof e.data.content === 'string' ? e.data.content : JSON.stringify(e.data.content);
      for (const s of allSkills) {
        if (txt.includes(s)) mentionedSessions[s].add(sid);
      }
    }
  }
}

console.log('=== SKILL USAGE SCAN ===');
console.log('session log files scanned:', files.length);
console.log('total skill tool invocations (matched):', totalCalls);
console.log('');
console.log('--- repo skills (with SKILL.md) ---');
for (const s of repoSkills) {
  console.log(`${s.padEnd(24)} invoked=${usedCounts[s]}  sessions=${usedSessions[s].size}  mentionedIn=${mentionedSessions[s].size}`);
}
console.log('');
console.log('--- other/built-in skills ---');
for (const s of extraSkills) {
  console.log(`${s.padEnd(24)} invoked=${usedCounts[s]}  sessions=${usedSessions[s].size}  mentionedIn=${mentionedSessions[s].size}`);
}
console.log('');
console.log('--- unknown skill names invoked (not in our list) ---');
for (const k of Object.keys(usedCounts).filter(k => k.startsWith('__'))) {
  console.log(`${k.slice(2).padEnd(24)} invoked=${usedCounts[k]}  sessions=${usedSessions[k].size}`);
}

