$targets = @(
  (Join-Path $env:USERPROFILE ".dsh\skills"),
  (Join-Path $env:USERPROFILE ".cursor\skills"),
  (Join-Path $env:USERPROFILE ".claude\skills")
)
$names = @("grill-me","i-have-adhd","long-form-corpus-rewrite")
foreach ($base in $targets) {
  if (-not (Test-Path $base)) { Write-Host "$base : NOT PRESENT (skip)"; continue }
  Write-Host "=== $base ==="
  foreach ($n in $names) {
    $p = Join-Path $base $n
    if (Test-Path $p) {
      $item = Get-Item $p
      Write-Host "  removing symlink/dir: $n (LinkType=$($item.LinkType))"
      Remove-Item $p -Force -Recurse 2>&1
    } else {
      Write-Host "  $n : already absent"
    }
  }
}
